using System.Text.Json;
using KingsValley.Core.Common;

namespace KingsValley.Core.Stages;

/// <summary>
/// Loads the stages extracted from the ROM (<c>Content/Rom/Levels/stageNN.json</c>, generated by
/// <c>tools/kv2-extract</c>). Pure C#: only <c>System.Text.Json</c>.
/// </summary>
public static class StageLoader
{
    private const string TerrainChars = ".?=#";

    /// <summary>Reads a stage from a JSON file.</summary>
    public static StageDefinition LoadFile(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException(
                $"Stage not found: '{path}'. Generate the data with tools/kv2-extract (see docs/ROM_EXTRACTION.md).", path);

        return Parse(File.ReadAllText(path));
    }

    /// <summary>Reads stage <paramref name="number"/> from the levels folder.</summary>
    public static StageDefinition Load(string levelsDirectory, int number)
        => LoadFile(Path.Combine(levelsDirectory, $"stage{number:D2}.json"));

    /// <summary>Interpreta o JSON de um stage.</summary>
    public static StageDefinition Parse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var ladders = ParseLadders(root.GetProperty("ladders"));
        var golden = ParseLadders(root.GetProperty("goldenLadders"));
        var mechanisms = (root.TryGetProperty("mechanisms", out var m) ? m : root.GetProperty("enemies"))
            .EnumerateArray().Select(ParseMechanism).ToList();
        var rooms = root.GetProperty("rooms").EnumerateArray().Select(ParseRoom).ToList();

        // The ROM writes value 1 (ladder) into the 0xE900 map, but the JSON flattens that value to '#'
        // (wall) in rooms[].rows. We reconcile: the cells covered by some ladder (normal
        // or golden) become TerrainKind.Ladder, so the room assembly matches the original.
        foreach (var ld in ladders.Concat(golden))
        {
            if (ld.Room < 1 || ld.Room > rooms.Count)
                continue;
            var room = rooms[ld.Room - 1];
            for (int r = ld.Row; r < ld.Row + ld.Length; r++)
                for (int c = ld.Column; c < ld.Column + 2; c++)
                {
                    if (r < 0 || r >= GameConstants.RoomRows || c < 0 || c >= GameConstants.RoomColumns)
                        continue;
                    room.Cells[r * GameConstants.RoomColumns + c] = TerrainKind.Ladder;
                }
        }

        // 63DA..6438: a mechanism writes WALL into the cells it occupies (width by type, height in
        // the 9th byte of the record); type 3 exits before writing (63B7). The JSON does not have that wall.
        foreach (var mech in mechanisms)
        {
            if (!mech.IsSolid || mech.Position.Room < 1 || mech.Position.Room > rooms.Count)
                continue;
            var room = rooms[mech.Position.Room - 1];
            int c0 = mech.Position.X >> 3, r0 = mech.Position.Y >> 3;
            if (mech.Kind == MechanismKind.Unknown2)
            {
                // In the ROM (63CC..63DA), type 2 only occupies 1 column of wall:
                // if Direction == 0: left column (c0)
                // if Direction == 1: right column (c0 + 1)
                int col = mech.Direction == 1 ? c0 + 1 : c0;
                for (int r = r0; r < r0 + mech.HeightCells; r++)
                {
                    if (r >= 0 && r < GameConstants.RoomRows && col >= 0 && col < GameConstants.RoomColumns)
                        room.Cells[r * GameConstants.RoomColumns + col] = TerrainKind.Wall;
                }
            }
            else
            {
                for (int r = r0; r < r0 + mech.HeightCells; r++)
                    for (int c = c0; c < c0 + mech.WidthCells; c++)
                    {
                        if (r < 0 || r >= GameConstants.RoomRows || c < 0 || c >= GameConstants.RoomColumns)
                            continue;
                        room.Cells[r * GameConstants.RoomColumns + c] = TerrainKind.Wall;
                    }
            }
        }

        return new StageDefinition
        {
            Number = root.GetProperty("stage").GetInt32(),
            RoomGrid = ParseGrid(root.GetProperty("roomGrid")),
            Rooms = rooms,
            Ladders = ladders,
            GoldenLadders = golden,
            Items = root.GetProperty("items").EnumerateArray()
                .Select(e => new ItemDefinition((ItemKind)e.GetProperty("type").GetInt32(), Point(e)))
                .ToList(),
            SoulStones = root.GetProperty("soulStones").EnumerateArray().Select(Point).ToList(),
            ExitDoor = ParseDoor(root.GetProperty("exitDoor")),
            Coffins = root.GetProperty("coffins").EnumerateArray()
                .Select(c => new CoffinDefinition(Point(c),
                    c.TryGetProperty("type", out var t) ? (EnemyKind)t.GetInt32() : EnemyKind.Mummy,
                    c.TryGetProperty("level", out var l) ? l.GetInt32() : 1))
                .ToList(),
            Mechanisms = mechanisms,
            PlayerStart = Point(root.GetProperty("playerStart")),
        };
    }

    private static StagePoint Point(JsonElement e) =>
        new(e.GetProperty("room").GetInt32(), e.GetProperty("x").GetInt32(), e.GetProperty("y").GetInt32());

    /// <summary>
    /// Reads a mechanism. The width comes from the type (table 0x6444 of bank 1: type 1 and 5 -> 2, type 4 -> 4,
    /// type 2 -> 2 cells wide graphically, type 3 -> 1) and the height from the 9th byte of the record (`raw`, the (IX+8) of 6364).
    /// </summary>
    private static MechanismDefinition ParseMechanism(JsonElement e)
    {
        var kind = (MechanismKind)e.GetProperty("type").GetInt32();
        int width = kind switch
        {
            MechanismKind.RotatingDoor => 2,
            MechanismKind.Unknown2 => 2,
            MechanismKind.MovableBlock => 2,
            MechanismKind.Unknown4 => 4,
            _ => 1,
        };
        int height = 1;
        int initialPhase = 0;
        int direction = 0;
        var raw = e.TryGetProperty("raw", out var r) ? r.GetString() : null;
        if (raw is { Length: >= 18 })
            height = Convert.ToInt32(raw.Substring(16, 2), 16);
        if (raw is { Length: >= 16 })
        {
            int byte7 = Convert.ToInt32(raw.Substring(14, 2), 16);
            direction = (byte7 & 2) != 0 ? 1 : 0;
        }
        // The rotation (IX+5) only holds for the swivel door (type 1): 3*(byte3&7) = 0 or 3.
        if (kind == MechanismKind.RotatingDoor && raw is { Length: >= 12 })
            initialPhase = Convert.ToInt32(raw.Substring(10, 2), 16);
        if (initialPhase is not (0 or 3)) initialPhase = 0;

        return new MechanismDefinition(kind, Point(e), width, height, initialPhase, direction);
    }

    private static DoorDefinition ParseDoor(JsonElement e) =>
        new(Point(e), Math.Max(1, e.GetProperty("w").GetInt32()), Math.Max(1, e.GetProperty("h").GetInt32()));

    private static int[,] ParseGrid(JsonElement grid)
    {
        var result = new int[8, 8];
        int r = 0;
        foreach (var row in grid.EnumerateArray())
        {
            int c = 0;
            foreach (var cell in row.EnumerateArray())
                result[r, c++] = cell.GetInt32();
            r++;
        }

        return result;
    }

    private static RoomDefinition ParseRoom(JsonElement room)
    {
        var cells = new TerrainKind[Common.GameConstants.RoomColumns * Common.GameConstants.RoomRows];
        int y = 0;
        foreach (var row in room.GetProperty("rows").EnumerateArray())
        {
            var text = row.GetString() ?? string.Empty;
            for (int x = 0; x < text.Length && x < Common.GameConstants.RoomColumns; x++)
            {
                int kind = TerrainChars.IndexOf(text[x]);
                cells[y * Common.GameConstants.RoomColumns + x] = kind < 0 ? TerrainKind.Empty : (TerrainKind)kind;
            }

            y++;
        }

        return new RoomDefinition
        {
            Index = room.GetProperty("index").GetInt32(),
            Cells = cells,
        };
    }

    private static List<LadderDefinition> ParseLadders(JsonElement list) =>
        list.EnumerateArray()
            .Select(e => new LadderDefinition(
                e.GetProperty("room").GetInt32(),
                e.GetProperty("col").GetInt32(),
                e.GetProperty("row").GetInt32(),
                e.GetProperty("length").GetInt32()))
            .ToList();
}
